INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (127802, 10007, "2023/09/15 15:00:00", 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 0.0, 1, 2, -470.0, 2002, 1, 0.0, "ヴルム", "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (127802, 10008, "2023/09/15 15:00:00", 1, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 6.5, 2, 2, -470.0, 2002, 2, 0.0, "ヴルム", "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (129602, 10009, "2023/12/15 15:00:00", 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 0.0, 1, 3, -470.0, 2002, 2, 0.0, "アネモネ", "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (129602, 10010, "2023/12/15 15:00:00", 1, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 0.0, 2, 3, -470.0, 2002, 2, 0.0, "アネモネ", "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (129701, 10011, "2023/12/15 15:00:00", 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 0.0, 1, 3, -470.0, 2002, 1, 0.0, "ネフィ=ネラ", "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (129701, 10012, "2023/12/15 15:00:00", 1, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 6.2, 2, 3, -470.0, 2002, 2, 0.0, "ネフィ=ネラ", "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130301, 10013, "2024/03/15 15:00:00", 5, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 3.1, 1, 4, -470.0, 2002, 3, 0.0, "カノン", "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130301, 10014, "2024/03/15 15:00:00", 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 6.15, 2, 4, -470.0, 2002, 3, 0.0, "カノン", "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130401, 10015, "2024/03/15 15:00:00", 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 0.0, 1, 4, -470.0, 2002, 2, 0.0, "ナーナ", "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130401, 10016, "2024/03/15 15:00:00", 1, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 3.35, 2, 4, -470.0, 2002, 2, 0.0, "ナーナ", "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130502, 10017, "2024/06/15 15:00:00", 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 0.0, 1, 5, -470.0, 2002, 1, 0.0, "ホウオウ", "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130502, 10018, "2024/06/15 15:00:00", 1, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 3.18, 2, 5, -470.0, 2002, 2, 0.0, "ホウオウ", "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130503, 10019, "2024/06/15 15:00:00", 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 0.0, 3, 5, -470.0, 2002, 4, 0.0, "ホウオウ", "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (123301, 10020, "2024/06/15 15:00:00", 2, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 4.9, 1, 5, -470.0, 2002, 1, 0.0, "ネア", "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (123301, 10021, "2024/06/15 15:00:00", 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 4.8, 2, 5, -470.0, 2002, 1, 0.0, "ネア", "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133301, 10022, "2024/09/15 15:00:00", 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 4.922, 1, 6, -470.0, 2002, 3, 0.0, "カリザ", "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133301, 10023, "2024/09/15 15:00:00", 5, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 9.638, 2, 6, -470.0, 2002, 3, 0.0, "カリザ", "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133401, 10024, "2024/09/15 15:00:00", 2, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2.88, 1, 6, -470.0, 2002, 1, 0.0, "ミーア", "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133401, 10025, "2024/09/15 15:00:00", 1, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 4.818, 2, 6, -470.0, 2002, 5, 0.0, "ミーア", "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133002, 10026, "2024/12/15 15:00:00", 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1.78, 1, 7, -470.0, 2002, 2, 0.0, "グレイス", "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133002, 10027, "2024/12/15 15:00:00", 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 6.15, 2, 7, -470.0, 2002, 1, 0.0, "グレイス", "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133102, 10028, "2024/12/15 15:00:00", 2, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 4.28, 1, 7, -470.0, 2002, 6, 0.0, "ヴァイオレット", "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (133102, 10029, "2024/12/15 15:00:00", 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 0.0, 2, 7, -470.0, 2002, 1, 0.0, "ヴァイオレット", "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (136902, 10030, "2025/03/15 15:00:00", 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 5.53, 1, 8, -470.0, 2002, 2, 0.0, "ルルィ", "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (136902, 10031, "2025/03/15 15:00:00", 7, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 6.05, 2, 8, -470.0, 2002, 9, 0.0, "ルルィ", "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (137001, 10032, "2025/03/15 15:00:00", 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 0.0, 1, 8, -470.0, 2002, 2, 0.0, "デュラン", "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (137001, 10033, "2025/03/15 15:00:00", 1, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 0.0, 2, 8, -470.0, 2002, 2, 0.0, "デュラン", "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135902, 10034, "2025/06/16 15:00:00", 2, "おう\n好きなもん持ってきな", 0.0, 1, 9, -470.0, 2002, 2, 0.0, "サツキ", "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135902, 10035, "2025/06/16 15:00:00", 6, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 4.935, 2, 9, -470.0, 2002, 1, 0.0, "サツキ", "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135802, 10036, "2025/06/16 15:00:00", 5, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 7.441, 1, 9, -470.0, 2002, 2, 0.0, "ユキノ", "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135802, 10037, "2025/06/16 15:00:00", 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 0.0, 2, 9, -470.0, 2002, 7, 0.0, "ユキノ", "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130901, 10038, "2025/09/16 15:00:00", 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2.295, 1, 10, -470.0, 2002, 2, 0.0, "クルル", "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (130901, 10039, "2025/09/16 15:00:00", 6, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6.281, 2, 10, -470.0, 2002, 1, 0.0, "クルル", "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (137701, 10040, "2025/09/16 15:00:00", 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 5.549, 1, 10, -470.0, 2002, 2, 0.0, "ヴォルガーノ", "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (137701, 10041, "2025/09/16 15:00:00", 6, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2.64, 2, 10, -470.0, 2002, 3, 0.0, "ヴォルガーノ", "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (132801, 10042, "2025/12/15 15:00:00", 4, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 7.642, 1, 11, -470.0, 2002, 7, 0.0, "ライラエル", "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (132802, 10043, "2025/12/15 15:00:00", 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 0.0, 2, 11, -470.0, 2002, 1, 0.0, "ライラエル", "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (134502, 10044, "2025/12/15 15:00:00", 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 0.0, 1, 11, -470.0, 2002, 1, 0.0, "クローチェ", "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (134501, 10045, "2025/12/15 15:00:00", 1, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 3.72, 2, 11, -470.0, 2002, 2, 0.0, "クローチェ", "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (138201, 10046, "2026/03/16 12:00:00", 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 4.991, 1, 12, -470.0, 2002, 2, 0.0, "ネフィ＝ネラ", "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (138201, 10047, "2026/03/16 12:00:00", 4, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 3.877, 2, 12, -470.0, 2002, 1, 0.0, "ネフィ＝ネラ", "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (136001, 10048, "2026/03/16 12:00:00", 6, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 1.71, 1, 12, -470.0, 2002, 4, 0.0, "アラクネ", "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (136001, 10049, "2026/03/16 12:00:00", 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 5.32, 2, 12, -470.0, 2002, 5, 0.0, "アラクネ", "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135401, 10050, "2026/06/15 12:00:00", 4, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 3.727, 1, 13, -470.0, 2002, 9, 0.0, "アネモネ", "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135401, 10051, "2026/06/15 12:00:00", 9, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 7.213, 2, 13, -470.0, 2002, 7, 0.0, "アネモネ", "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (135301, 10052, "2026/06/15 12:00:00", 2, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 1.874, 1, 13, -470.0, 2002, 1, 0.0, "クリア", "2026/09/22 11:59:59");
